code='''def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid))
    marks=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]!=bg]
    rays=set()
    for r,c,v in marks:
        for dr in (1,):
            for dc in (-1,1):
                if r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==v:
                    rays.add((r+dr,c+dc,v,dr,dc))
    for r,c,v,dr,dc in rays:
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w:
            out[rr][cc]=v; rr+=dr; cc+=dc
    return out
'''; p.write_text(code); exec(code); print(transform(grid))

